import{_ as o,o as i,c as n,a3 as a}from"./chunks/framework.CRbjHCyB.js";const u=JSON.parse('{"title":"Feature Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"clice/changelog/feature-changelog.md","filePath":"en/clice/changelog/feature-changelog.md"}'),t={name:"clice/changelog/feature-changelog.md"};function r(s,e,c,d,l,h){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="feature-changelog" tabindex="-1">Feature Changelog <a class="header-anchor" href="#feature-changelog" aria-label="Permalink to &quot;Feature Changelog&quot;">​</a></h1><p>This file tracks user-facing feature changes across clice releases. Each release section documents new features, breaking changes, and deprecations.</p><h2 id="v1-0-0-upcoming" tabindex="-1">v1.0.0 (upcoming) <a class="header-anchor" href="#v1-0-0-upcoming" aria-label="Permalink to &quot;v1.0.0 (upcoming)&quot;">​</a></h2><p>v1.0 ships first as rolling beta releases (<code>v1.0.0-beta.1</code>, <code>beta.2</code>, …) for a public trial period; fixes land continuously in small versions with no code freeze, and the final <code>v1.0.0</code> is tagged once the trial settles. This entry summarizes everything user-visible since the <code>v0.1.0-alpha</code> series.</p><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Multi-process architecture.</strong> Compilation runs in worker subprocesses coordinated by a master process, so a compiler crash on one translation unit no longer takes down the whole session — the crashed worker is respawned and its documents recover on demand. Stateful workers cap resident documents with LRU eviction, and the pool sheds background load under system memory pressure.</li><li><strong>Compilation contexts for headers.</strong> Opening a header compiles it in the context of a source file that includes it: clice reconstructs the include chain into a synthesized preamble (and a synthesized suffix for X-macro/<code>.def</code> fragments), so symbols that depend on the includer&#39;s macros resolve correctly. Editors can list and switch the active context through the <code>clice/queryContext</code>, <code>clice/currentContext</code>, and <code>clice/switchContext</code> extensions — the same mechanism switches between multiple compile-database entries for one file. Self-contained headers are detected and compiled directly.</li><li><strong>LSP feature surface.</strong> Hover (definition printing, documentation, record layout with size/offset/padding, expression values, <code>auto</code>/<code>decltype</code> deduction); code completion with signature details, parameter snippets, deprecation strikethrough, and <code>#include</code>/<code>import</code> path completion; signature help; go-to definition (including on <code>#include</code> lines and module names), declaration, implementation, type definition, and find references, served from the project index; document symbols; semantic tokens with rich modifiers; inlay hints; folding ranges; document links (including inside the preamble, and <code>#embed</code>); <code>.clang-format</code>-based formatting and range formatting; call hierarchy and type hierarchy; workspace symbol search; published diagnostics; inactive-region greying for code disabled by <code>#if</code> (<code>clice/inactiveRegions</code> extension).</li><li><strong>Background indexing.</strong> A persistent project-wide index powers cross-file features without opening every file. Indexing piggybacks on compilations that already happen, runs concurrently at low priority, pauses for interactive requests, reports LSP <code>$/progress</code>, and survives restarts. Two-layer staleness detection (mtime, then content hash) keeps <code>touch</code> and <code>git checkout</code> from triggering needless rebuilds.</li><li><strong>Out-of-band change tracking.</strong> A stat-polling file tracker picks up changes made outside the editor — a regenerated <code>compile_commands.json</code>, a <code>git checkout</code>, code generators — without restarting the server.</li><li><strong>C++20 named modules.</strong> Module interfaces are compiled on demand through a pull-based dependency graph with PCM caching; <code>import</code> completion and go-to-definition on module names included.</li><li><strong>Unified on-disk cache.</strong> PCH, PCM, and index artifacts live in one content-addressed store with crash-safe writes, shared across sessions and restarts; the rebuildable artifacts (PCH/PCM) are evicted under a size bound.</li><li><strong>Configuration.</strong> <code>clice.toml</code> (or <code>.clice/config.toml</code>) plus LSP <code>initializationOptions</code> overlay; per-file <code>[[rules]]</code> with glob patterns to append/remove compile flags; <code>[tracker]</code> polling intervals; XDG-based cache paths with <code>${workspace}</code> substitution. Malformed configuration is reported with line/column as diagnostics on the config file.</li><li><strong>Tooling API.</strong> A JSON-RPC API over TCP for AI agents and external tools: project files, symbol search, reading full symbol bodies, definitions/references, call graph, and type hierarchy — plus the <code>clice query</code> CLI.</li><li><strong>Editor extensions.</strong> In-repo extensions for VS Code (published on the Marketplace), Neovim, and Zed.</li><li><strong>Operability.</strong> Per-session file logging with crash capture, user-facing guidance via <code>window/logMessage</code> when the setup is broken (e.g. no compilation database), LSP session recording for replay (<code>--record</code>), and an accurate <code>--version</code> that matches the release tag.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Configuration file location.</strong> The <code>config</code> CLI option is gone; configuration is read from <code>${workspace}/clice.toml</code> (or <code>${workspace}/.clice/config.toml</code>).</li><li><strong>Config key rename.</strong> <code>compile_commands_dirs</code> is now <code>compile_commands_paths</code>; the old key is ignored.</li><li><strong>Upgrading from 0.x rebuilds caches.</strong> The on-disk cache and index formats changed; the first launch after upgrading discards old artifacts and re-indexes the project once. This also retires PCHs produced by older versions whose cache key ignored compile flags — those could serve results with the wrong macro configuration.</li><li><strong>Toolchain baseline.</strong> clice now builds against LLVM/Clang 21.1.8, with prebuilt release binaries for Linux, macOS, and Windows on both x64 and arm64.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Rapid consecutive edits no longer produce spurious &quot;redefinition&quot; errors from a compile/update race.</li><li>Several worker crashes on malformed input (null AST consumer, invalid file IDs, missing cache directories) fixed; crashes that do happen are contained by process isolation.</li><li>Documents evicted from a worker&#39;s LRU no longer silently lose hover/semantic tokens — they recompile on the next request.</li><li>Lifecycle edge cases: a <code>didOpen</code> racing ahead of the <code>initialize</code> handshake is accepted; unknown enum values from newer LSP clients no longer fail the handshake; diagnostics produced before the client was ready are replayed after <code>initialized</code>.</li><li>Saving a header now correctly reindexes closed files that include it, keeping cross-file references fresh.</li></ul><h3 id="known-gaps" tabindex="-1">Known gaps <a class="header-anchor" href="#known-gaps" aria-label="Permalink to &quot;Known gaps&quot;">​</a></h3><ul><li>Code completion, navigation, document links, and diagnostics are functional but not yet complete (see the feature overview pages for per-feature status).</li><li>Code actions are not implemented yet (and not advertised).</li><li>clang-tidy runs as a batch pass through <code>clice lint</code>; live clang-tidy diagnostics in the editor are planned.</li></ul>',12)])])}const p=o(t,[["render",r]]);export{u as __pageData,p as default};
